// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;

import org.eclipse.rdf4j.sail.lmdb.LmdbAdjacencyMemoryAccount.MemoryKind;
import org.eclipse.rdf4j.sail.lmdb.LmdbAdjacencyMetrics.FallbackReason;
import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Plan 27 Milestone 7: overlay consolidation and the no-overlap quiescent rebuild. Retained old states keep pinned
 * snapshots exact across consolidation; released views allow charge reclamation; the rebuild protocol makes new
 * acquisitions fall back while an existing lease finishes, then serves again from a fresh base.
 */
class LmdbDirectAdjacencyConsolidationTest {

	private TripleStore tripleStore;
	private LmdbDirectAdjacencyStore store;

	private static long uri(long payload) {
		return ValueIds.createId(ValueIds.T_URI, payload);
	}

	private static final long S1 = uri(1);
	private static final long P1 = uri(100);
	private static final long O_BASE = uri(1000);

	@BeforeEach
	void setUp(@TempDir File dataDir) throws Exception {
		tripleStore = new TripleStore(dataDir, new LmdbStoreConfig("spoc,posc"), null);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbDirectAdjacencyOptions options = LmdbDirectAdjacencyOptions.resolve(config, Runtime.getRuntime()
				.maxMemory(), name -> null, 4);
		store = new LmdbDirectAdjacencyStore(tripleStore, null, new AtomicBoolean(false), options);
		tripleStore.setDirectAdjacencyCommitHooks(store.commitListener(), store.newCommitDelta());
	}

	@AfterEach
	void tearDown() throws Exception {
		if (store != null) {
			store.close();
		}
		if (tripleStore != null) {
			tripleStore.close();
		}
	}

	private void commitAdd(long s, long p, long o) throws IOException {
		tripleStore.startTransaction();
		tripleStore.storeTriple(s, p, o, 0, true);
		tripleStore.commit();
		store.applyCommitted(tripleStore.drainDirectAdjacencyCommitDelta());
	}

	private List<long[]> probe(LmdbAdjacencyReadView view, long s, long p) throws IOException {
		RecordIterator it = store.tryOpen(view, null, s, p, -1, -1, true);
		assertThat(it).as("probe %d/%d must be served", s, p).isNotNull();
		List<long[]> rows = new ArrayList<>();
		try {
			long[] quad;
			while ((quad = it.next()) != null) {
				rows.add(quad.clone());
			}
		} finally {
			it.close();
		}
		return rows;
	}

	@Test
	void twelveCommitsConsolidateAndStayExact() throws Exception {
		commitAdd(S1, P1, O_BASE);
		assertThat(store.buildNowForTest()).isTrue();

		for (int i = 1; i <= 12; i++) {
			commitAdd(S1, P1, uri(1000 + i));
			store.pauseApplierForTest(false); // apply each commit deterministically: consolidation is the subject
		}
		LmdbAdjacencyPublishedState state = store.publishedStateForTest();
		assertThat(state.overlays()).isNotNull();
		assertThat(state.overlays().generationCount())
				.isLessThanOrEqualTo(store.options().maxDeltaGenerations());
		try (LmdbAdjacencyReadView view = store.acquire(tripleStore.getDataRevision())) {
			assertThat(view.isExact())
					.as("fallback=%s maintenance=%s applied=%d data=%d min=%d", view.fallbackReason(),
							store.maintenanceState(), state.appliedRevision(), tripleStore.getDataRevision(),
							state.minSnapshotRevision())
					.isTrue();
			assertThat(probe(view, S1, P1)).hasSize(13);
		}
	}

	@Test
	void pinnedViewRetainsItsVersionsAcrossConsolidationAndReleaseReclaims() throws Exception {
		commitAdd(S1, P1, O_BASE);
		assertThat(store.buildNowForTest()).isTrue();
		commitAdd(S1, P1, uri(1001));
		commitAdd(S1, P1, uri(1002));
		store.pauseApplierForTest(false);
		long pinnedRevision = tripleStore.getDataRevision();
		long deltaBytesWhilePinned;
		LmdbAdjacencyReadView pinned = store.acquire(pinnedRevision);
		try {
			assertThat(pinned.isExact()).isTrue();

			for (int i = 3; i <= 14; i++) {
				commitAdd(S1, P1, uri(1000 + i));
				store.pauseApplierForTest(false);
			}

			// the pinned view keeps serving its own snapshot exactly through its retained state
			assertThat(probe(pinned, S1, P1)).hasSize(3);
			try (LmdbAdjacencyReadView latest = store.acquire(tripleStore.getDataRevision())) {
				assertThat(probe(latest, S1, P1)).hasSize(15);
			}
			deltaBytesWhilePinned = store.memoryAccount().chargedBytes(MemoryKind.DELTA);
		} finally {
			pinned.close();
		}
		long deltaBytesAfterRelease = store.memoryAccount().chargedBytes(MemoryKind.DELTA);
		assertThat(deltaBytesAfterRelease).isLessThan(deltaBytesWhilePinned);
	}

	@Test
	void lateAcquisitionBelowTheConsolidationFloorFallsBack() throws Exception {
		commitAdd(S1, P1, O_BASE);
		assertThat(store.buildNowForTest()).isTrue();
		long earlyRevision = tripleStore.getDataRevision();
		for (int i = 1; i <= 12; i++) {
			commitAdd(S1, P1, uri(1000 + i));
			store.pauseApplierForTest(false);
		}
		// consolidation squashed history: a late acquisition for the early snapshot must decline, never guess
		try (LmdbAdjacencyReadView lateView = store.acquire(earlyRevision)) {
			assertThat(lateView.isExact()).isFalse();
			assertThat(lateView.fallbackReason()).isEqualTo(FallbackReason.SNAPSHOT_BEFORE_BASE);
		}
	}

	@Test
	void quiescentRebuildWaitsForTheLeaseAndServesAgain() throws Exception {
		commitAdd(S1, P1, O_BASE);
		assertThat(store.buildNowForTest()).isTrue();
		commitAdd(S1, P1, uri(1001));
		store.pauseApplierForTest(false);

		LmdbAdjacencyReadView held = store.acquire(tripleStore.getDataRevision());
		try {
			assertThat(held.isExact()).isTrue();
			store.scheduleQuiescentRebuild();
			// wait until the UNAVAILABLE state is published, then prove both properties of the quiesce window
			long deadline = System.nanoTime() + 10_000_000_000L;
			while (store.publishedStateForTest()
					.servingState() != LmdbAdjacencyPublishedState.AdjacencyServingState.UNAVAILABLE) {
				if (System.nanoTime() > deadline) {
					throw new AssertionError("quiescent rebuild never published the UNAVAILABLE state");
				}
				Thread.onSpinWait();
			}
			try (LmdbAdjacencyReadView duringQuiesce = store.acquire(tripleStore.getDataRevision())) {
				assertThat(duringQuiesce.isExact()).isFalse();
				assertThat(duringQuiesce.fallbackReason()).isEqualTo(FallbackReason.BUILDING);
			}
			// the existing lease keeps serving from its retained state while the rebuild waits
			assertThat(probe(held, S1, P1)).hasSize(2);
		} finally {
			held.close();
		}

		long deadline = System.nanoTime() + 10_000_000_000L;
		while (store.maintenanceState() != LmdbDirectAdjacencyStore.MaintenanceState.ACTIVE) {
			if (System.nanoTime() > deadline) {
				throw new AssertionError("quiescent rebuild never completed after the lease closed");
			}
			Thread.onSpinWait();
		}
		try (LmdbAdjacencyReadView rebuilt = store.acquire(tripleStore.getDataRevision())) {
			assertThat(rebuilt.isExact()).isTrue();
			assertThat(probe(rebuilt, S1, P1)).hasSize(2);
		}
	}

	@Test
	void repeatedRebuildsAndCloseLeakNoChargedBytes() throws Exception {
		commitAdd(S1, P1, O_BASE);
		assertThat(store.buildNowForTest()).isTrue();
		for (int i = 1; i <= 12; i++) {
			commitAdd(S1, P1, uri(1000 + i));
			store.pauseApplierForTest(false);
		}
		assertThat(store.rebuildNowForTest()).isTrue();
		assertThat(store.rebuildNowForTest()).isTrue();
		try (LmdbAdjacencyReadView view = store.acquire(tripleStore.getDataRevision())) {
			assertThat(probe(view, S1, P1)).hasSize(13);
		}
		LmdbAdjacencyMemoryAccount account = store.memoryAccount();
		store.close();
		store = null;
		assertThat(account.totalChargedBytes()).isZero();
	}
}
